
import SPServices from "../../../../../services/SPService/spservice";
import { ListNames, StatusId } from "../../../../../utilities/Config";

export interface ScorecardJobRow {
  id:           string;
  recruitmentID: number;
  jobCode:      string;
  jobCodeID:    number;
  jobTitle:     string;
  department:   string;
  nationality:  string;
  statusId:     number;
  status:       string;
  grade:        string;
  interviewLevel: string;
  noOfPositions: number;
}

export interface ScorecardCandidateRow {
  id:            number;
  recruitmentID: number;
  jobCode:       string;
  jobCodeID:     number;
  fullName:      string;
  nationality:   string;
  gender:        string;
  status:        string;
  statusId:      number;
  interviewDate: string;
  interviewLevel:string;
  grade:         string;
  department:    string;
  gpa:           string;
}

// HOD scorecard status IDs — from old CandidateList.tsx
export const HOD_SCORECARD_STATUS_IDS = [
  131, // PendingwithHODtoselectthecandidate
  133, // Selected
  132, // OnHoldbyHOD
  134, // RejectedbyHOD
  130, // PendingwithHODtoAssignPositionID
  138, // PendingwithHODtoselectthecandidateLevel2
  139, // CandidateOnHoldbyHODLevel1
  140, // CandidateOnHoldbyHODLevel2
  141, // CandidateRejectedbyHODLevel1
  142, // CandidateRejectedbyHODLevel2
];

// ── Fetch positions (job-level list) for HOD scorecard tab ────
export async function fetchScorecardJobList(): Promise<ScorecardJobRow[]> {
  try {
    const res: any[] =  await SPServices.SPReadItems({
      Listname:        ListNames.HRMSRecruitmentDptDetails,
      Select:          "*,Department/DepartmentName,Status/StatusDescription,JobCode/JobCode,JobCode/ID,BusinessUnitCode/BusineesUnitCode,PatersonGrade/PatersonGrade",
      Expand:          "Department,Status,JobCode,BusinessUnitCode,PatersonGrade",
      FilterCondition: "and",
      Filter: [
        {
          FilterKey:   "StatusId",
          Operator:    "in",
          FilterValue: [
            StatusId.PendingwithHODtoAssignPositionID,
            131, 132, 133, 134, 138, 139, 140, 141, 142,
          ],
        },
        { FilterKey: "ItemCreated", Operator: "eq", FilterValue: "No" },
      ],
      Topcount:        1000,
      Orderby:         "ID",
      Orderbydecorasc: true,
    });

    return res.map((item: any) => ({
      id:             String(item.ID),
      recruitmentID:  item.ID,
      jobCode:        item.JobCode?.JobCode || "",
      jobCodeID:      item.JobCode?.ID      || item.JobCodeId || 0,
      jobTitle:       item.JobTitleEnglish  || item.Title || "",
      department:     item.Department?.DepartmentName || "",
      nationality:    item.Nationality      || "",
      statusId:       item.StatusId         || 0,
      status:         item.Status?.StatusDescription || "",
      grade:          item.PatersonGrade?.PatersonGrade || "",
      interviewLevel: "",
      noOfPositions:  item.NumberOfPersonNeeded || 1,
    }));
  } catch (e) {
    console.error("[fetchScorecardJobList]", e);
    return [];
  }
}

// ── Fetch candidates for a specific job (recruitment ID) ──────
export async function fetchCandidatesForJob(
  recruitmentID: number,
  jobCodeID:     number,
  employeeList:  any[]
): Promise<ScorecardCandidateRow[]> {
  try {
    const res: any[] =  await SPServices.SPReadItems({
      Listname:        ListNames.HRMSRecruitmentCandidatePersonalDetails,
      Select:          "*,RecruitmentID/ID,JobCode/JobCode,Status/StatusDescription,Status/ID",
      Expand:          "RecruitmentID,JobCode,Status",
      FilterCondition: "and",
      Filter: [
        { FilterKey: "RecruitmentIDId", Operator: "eq", FilterValue: recruitmentID },
        { FilterKey: "JobCodeId",        Operator: "eq", FilterValue: jobCodeID },
        { FilterKey: "StatusId",         Operator: "in", FilterValue: HOD_SCORECARD_STATUS_IDS },
        { FilterKey: "ItemCreated",      Operator: "eq", FilterValue: "No" },
      ],
      Topcount: 500,
    });

    return res.map((item: any) => ({
      id:             item.ID,
      recruitmentID:  item.RecruitmentID?.ID || item.RecruitmentIDId || recruitmentID,
      jobCode:        item.JobCode?.JobCode || "",
      jobCodeID:      item.JobCodeId || jobCodeID,
      fullName:       [item.FristName, item.MiddleName, item.LastName].filter(Boolean).join(" ").trim(),
      nationality:    item.Nationality    || "",
      gender:         item.Gender         || "",
      status:         item.Status?.StatusDescription || "",
      statusId:       item.StatusId       || 0,
      interviewDate:  item.InterviewDate  || "",
      interviewLevel: item.InterviewLevel || "",
      grade:          item.JobGrade       || "",
      department:     item.Department     || "",
      gpa:            item.GPA            || "",
    }));
  } catch (e) {
    console.error("[fetchCandidatesForJob]", e);
    return [];
  }
}
